query getTrendWithRange($filter: Filter, $startTsSec: Long, $endTsSec: Long) {
  trend(filter: $filter, startTsSec: $startTsSec, endTsSec: $endTsSec) {
    dexTrend {
      ...ScoreTrendNodeCommon
    }
    technologyTrend {
      ...ScoreTrendNodeCommon
    }
    sentimentTrend {
      ...ScoreTrendNodeCommon
    }
  }
}


fragment ScoreTrendNodeCommon on TrendNodeScore {
  startDate
  endDate
  value
  userCount
}
